def test_normalize_vote_tally() -> None:
    """Vote tally '9-0' -> spoken 'nine to zero'."""
    assert normalize_vote_tally("9-0") == ["nine to zero"]
    assert normalize_vote_tally("7-2") == ["seven to two"]
    assert normalize_vote_tally("5-4") == ["five to four"]


def test_normalize_year() -> None:
    """Four-digit year -> spoken form."""
    assert normalize_year("1999") == ["nineteen ninety nine"]
    assert normalize_year("2020") == ["twenty twenty"]
    assert normalize_year("1954") == ["nineteen fifty four"]


def test_normalize_roman_numeral() -> None:
    """Roman numeral (II-XII) -> spoken number."""
    assert normalize_roman_numeral("VII") == ["seven"]
    assert normalize_roman_numeral("IV") == ["four"]
    assert normalize_roman_numeral("II") == ["two"]
    assert normalize_roman_numeral("XII") == ["twelve"]


def test_normalize_percentage() -> None:
    """Percentage span -> spoken form."""
    assert normalize_percentage("50%") == ["fifty percent"]
    assert normalize_percentage("25 percent") == ["twenty five percent"]
    assert normalize_percentage("100%") == ["one hundred percent"]


def test_normalize_decade() -> None:
    """Decade span (e.g. 1980s, 20s) -> spoken form."""
    assert normalize_decade("1860s") == ["eighteen sixties"]
    assert normalize_decade("1980s") == ["nineteen eighties"]
    assert normalize_decade("1930s") == ["nineteen thirties"]
    assert normalize_decade("2010s") == ["twenty tens"]
    assert normalize_decade("2020s") == ["twenty twenties"]
    assert normalize_decade("20s") == ["twenties"]
    assert normalize_decade("50s") == ["fifties"]
    assert normalize_decade("10s") == ["tens"]


def test_normalize_vote_tally_invalid_returns_empty_or_unchanged() -> None:
    """Invalid vote tally format does not crash; returns sensible default."""
    result = normalize_vote_tally("12-3")  # not single digits
    assert isinstance(result, list)
    assert len(result) >= 1  # may still produce a best-effort


def test_latin_simple_map() -> None:
    """Latin accented chars map to ASCII (NFD strip)."""
    assert latin_simple_map("café") == "cafe"
    assert latin_simple_map("naïve") == "naive"
    assert latin_simple_map("Espańola") == "Espanola"
    assert latin_simple_map("vis-à-vis") == "vis-a-vis"


def test_normalize_latin_returns_list_of_dicts_with_method() -> None:
    """normalize_latin returns list of {text, method}; first is simple_map."""
    result = normalize_latin("café")
    assert isinstance(result, list)
    assert len(result) >= 1
    first = result[0]
    assert "text" in first and "method" in first
    assert first["method"] == "simple_map"
    assert first["text"] == "cafe"
    for item in result:
        assert "text" in item and "method" in item


def test_normalize_single_letter_parens() -> None:
    """Single letter in parentheses -> letter pronunciation (lowercase)."""
    assert normalize_single_letter_parens("(a)") == ["ay"]
    assert normalize_single_letter_parens("(b)") == ["bee"]
    assert normalize_single_letter_parens("(c)") == ["cee"]
    assert normalize_single_letter_parens("(A)") == ["ay"]
    assert normalize_single_letter_parens("(z)") == ["zee"]


def test_normalize_single_letter_parens_with_spaces() -> None:
    """Single letter in parens with optional spaces -> letter pronunciation."""
    assert normalize_single_letter_parens("(a )") == ["ay"]
    assert normalize_single_letter_parens("( b)") == ["bee"]
    assert normalize_single_letter_parens("( c )") == ["cee"]


def test_normalize_single_letter_parens_invalid_returns_span() -> None:
    """Invalid spans (ab), () return list with original span."""
    assert normalize_single_letter_parens("(ab)") == ["(ab)"]
    assert normalize_single_letter_parens("()") == ["()"]


def test_normalize_number_parens() -> None:
    """Number in parentheses -> spoken number."""
    assert normalize_number_parens("(1)") == ["one"]
    assert normalize_number_parens("(5)") == ["five"]
    assert normalize_number_parens("(32)") == ["thirty two"]
    assert normalize_number_parens("(0)") == ["zero"]


def test_normalize_number_parens_with_spaces() -> None:
    """Number in parens with optional spaces -> spoken number."""
    assert normalize_number_parens("( 12)") == ["twelve"]
    assert normalize_number_parens("(32 )") == ["thirty two"]
    assert normalize_number_parens("( 5 )") == ["five"]


def test_normalize_number_parens_invalid_returns_span() -> None:
    """Invalid (1a), () return list with original span."""
    assert normalize_number_parens("(1a)") == ["(1a)"]
    assert normalize_number_parens("()") == ["()"]


def test_normalize_non_speech_brackets() -> None:
    """Inaudible, Laughter, Laughs, Applause etc. -> empty string."""
    assert normalize_non_speech_brackets("(Inaudible)") == [""]
    assert normalize_non_speech_brackets("(Laughter)") == [""]
    assert normalize_non_speech_brackets("[Laughter]") == [""]
    assert normalize_non_speech_brackets("(Laughs)") == [""]
    assert normalize_non_speech_brackets("[Laughs]") == [""]
    assert normalize_non_speech_brackets("(Applause)") == [""]


def test_normalize_non_speech_brackets_unknown_returns_span() -> None:
    """Unknown content returns list with original span."""
    assert normalize_non_speech_brackets("(Section 3)") == ["(Section 3)"]


def test_normalize_non_speech_brackets_unbracketed() -> None:
    """Unbracketed Generallaughter. / General laughter. -> empty."""
    assert normalize_non_speech_brackets("Generallaughter.") == [""]
    assert normalize_non_speech_brackets("General laughter.") == [""]
    assert normalize_non_speech_brackets("GENERAL LAUGHTER") == [""]


def test_normalize_digit_letter_mixed() -> None:
    """Digit-letter mixed (2d, A2, 640L, 707{b}, 1392(d)) -> spoken form."""
    assert normalize_digit_letter_mixed("2d") == ["two dee"]
    assert normalize_digit_letter_mixed("A2") == ["ay two"]
    assert normalize_digit_letter_mixed("640L") == ["six forty ell"]
    assert normalize_digit_letter_mixed("M50") == ["em fifty"]
    assert normalize_digit_letter_mixed("707{b}") == ["seven oh seven bee"]
    assert normalize_digit_letter_mixed("1392(d)") == ["thirteen ninety two dee"]


def test_normalize_known_names() -> None:
    """Known names (McLaughlin, FitzGerald) -> identity (handled, no correction)."""
    assert normalize_known_names("McLaughlin") == ["McLaughlin"]
    assert normalize_known_names("McCoy") == ["McCoy"]
    assert normalize_known_names("FitzGerald") == ["FitzGerald"]


def test_normalize_numbered_list_marker() -> None:
    """Numbered list marker 1) -> one, 5) -> five."""
    assert normalize_numbered_list_marker("1)") == ["one"]
    assert normalize_numbered_list_marker("5)") == ["five"]
    assert normalize_numbered_list_marker("12)") == ["twelve"]


def test_normalize_dash() -> None:
    """Non-standard dash or dash sequence -> single standard dash."""
    assert normalize_dash("\u2013") == ["-"]  # en dash
    assert normalize_dash("\u2014") == ["-"]  # em dash
    assert normalize_dash("--") == ["-"]
    assert normalize_dash("---") == ["-"]
    assert normalize_dash("\u2013\u2014") == ["-"]  # en then em
    assert normalize_dash("\u2026") == ["-"]  # horizontal ellipsis
    assert normalize_dash("...") == ["-"]  # ASCII dot ellipsis
    assert normalize_dash("(.)") == ["-"]  # parenthesized dot


def test_normalize_ordinal() -> None:
    """Ordinal span -> spoken ordinal."""
    assert normalize_ordinal("37th") == ["thirty seventh"]
    assert normalize_ordinal("3rd") == ["third"]
    assert normalize_ordinal("1st") == ["first"]
    assert normalize_ordinal("21st") == ["twenty first"]


def test_normalize_ordinal_invalid_returns_span() -> None:
    """Invalid ordinal (no suffix) returns list with original span."""
    assert normalize_ordinal("12") == ["12"]
